function abHeal(z){z.s=Math.max(0,z.s-1);if(z.s<=0){const Z=abSc();Z.splice(Z.indexOf(z),1);soulMem('heal','ก้าวผ่านความกลัวที่ชั้น '+z.d+' ของ '+BIO[z.bi].n+' ได้แล้ว',4,'🌤️','win');soulShift({bold:3});return true;}return false;}
